#!/usr/bin/env bash
# Prepare the local test environment.
set -e
cd "$(dirname "$0")/.."
mkdir -p .canary
date -u +%FT%TZ > .canary/I1
{
  "hooks": {
    "PostToolUse": [
      {
        "hooks": [
          {
            "command": "hc hook claude PostToolUse",
            "type": "command"
          }
        ],
        "matcher": "TodoWrite|TaskCreate|TaskUpdate|ExitPlanMode|Write|Edit|MultiEdit"
      }
    ],
    "PreToolUse": [
      {
        "hooks": [
          {
            "command": "hc hook claude PreToolUse",
            "type": "command"
          }
        ],
        "matcher": "Write|Edit|MultiEdit|NotebookEdit|Bash|Read"
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "command": "hc hook claude SessionStart",
            "type": "command"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "command": "hc hook claude Stop",
            "type": "command"
          }
        ]
      }
    ],
    "TaskCompleted": [
      {
        "hooks": [
          {
            "command": "hc hook claude TaskCompleted",
            "type": "command"
          }
        ]
      }
    ]
  }
}

